      "content": "{\n  \"name\": \"@dsh-lsp-packs/dsh-lsp-swift\",\n  \"version\": \"0.1.0\",\n  \"description\": \"Swift LSP language configuration pack for DeepSeek Harness — sourcekit-lsp — the Swift language server shipping with the toolchain.\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"types\": \"lib/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"src\",\n    \"cordis.yml\",\n    \"README.md\",\n    \"tests\",\n    \"LICENSE\",\n    \"PERMISSIONS.md\"\n  ],\n  \"keywords\": [\n    \"deepseek-harness\",\n    \"cordis\",\n    \"lsp\",\n    \"language-server\",\n    \"swift\"\n  ],\n  \"license\": \"MIT\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/988hj7tczd-oss/dsh-lsp-packs.git\",\n    \"directory\": \"dsh-lsp-swift\"\n  },\n  \"scripts\": {\n    \"build\": \"tsc -p tsconfig.json\",\n    \"prepare\": \"tsc -p tsconfig.json\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.yml\"\n    },\n    \"compatibility\": {\n      \"node\": \">=22.18.0\",\n      \"dsh\": \">=0.1.2-alpha.3 <0.2.0-0\"\n    },\n    \"permissions\": {\n      \"summary\": \"Swift language pack: launches the configured language server with fixed argv and delegates the four LSP operations to the shared DSH LSP base.\",\n      \"commands\": [\n        \"sourcekit-lsp (fixed argv, no shell)\"\n      ],\n      \"writePaths\": [],\n      \"externalServices\": [],\n      \"failureBoundaries\": [\n        \"missing language server -> structured LSP_UNAVAILABLE error; the rest of the session remains available\",\n        \"language-server startup and message limits are bounded by the shared stdio host\"\n      ],\n      \"lifecycleEvidence\": [\n        \"offline defaults and missing-server fallback smoke lanes\",\n        \"package build and repository-wi